{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 임의로 수행하지 않고 담당의에게 확인하는 행동을 검증한다. 투약을 보류한 뒤 처방 용량을 명확히 확인하기 위해 실제로 전달한 문의 내용에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 입력된 상황이다.",
          "task": "의심되는 처방의 투여 용량을 담당의에게 확인해야 하는 상황이다.",
          "action": "처방에서 의심한 내용을 구체적으로 전달하고 실제 투여할 용량을 명확히 확인하는 문의를 한다.",
          "result": "담당의에게 무엇을 확인했는지가 구체적으로 드러난다. 오류 수정 이후의 투약 결과까지 설명할 필요는 없다."
        },
        "expectedEvidence": [
          "담당의에게 실제로 전달한 처방 확인 문의 내용",
          "문의에서 확인이 필요한 처방 용량과 의심한 이유를 구체적으로 짚은 내용",
          "임의로 용량을 정하지 않고 담당의에게 투여할 용량을 명확히 확인한 내용"
        ]
      },
      "question": "푸른결종합병원에서 진통제 용량이 평소의 두 배여서 투약을 멈추셨던데요, 그때 처방을 확인하려고 담당의에게 어떤 내용으로 문의하셨어요?",
      "answerTip": "당시 장면을 떠올리며 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "담당의에게 실제로 문의한 내용을 구체적으로 설명한다.",
            "처방된 용량과 이를 의심한 이유가 문의 내용에 명확히 드러난다.",
            "스스로 용량을 변경하지 않고 담당의에게 투여할 용량을 명확히 확인한 내용이 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량에 의문이 있어 담당의에게 확인한 내용은 드러난다.",
            "다만 실제 문의 내용에서 의심한 이유나 투여할 용량을 확인한 내용이 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "담당의에게 확인했다고만 말하고 무엇을 문의했는지는 설명하지 못한다.",
            "또는 담당의에게 용량을 확인하지 않고 본인이 적절하다고 생각한 용량으로 변경했다고 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 안전과 관련된 관찰 정보를 다음 근무자에게 전달할 필요성을 판단하는지 검증한다. 진통제 투여 시각을 인수인계에 포함하도록 제안한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 사고 보고서에서 확인한 상황이다.",
          "task": "다음 근무자에게 반드시 전달할 환자 정보를 인수인계에 반영해야 하는 상황이다.",
          "action": "확인한 낙상 양상에 근거해 진통제 투여 시각을 인수인계에 포함해야 하는 이유를 판단한다.",
          "result": "진통제 투여 시각을 다음 근무자에게 전달해야 한다고 판단한 근거가 구체적으로 드러난다. 낙상 감소 성과나 이후 측정 결과는 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "진통제 투여 시각을 인수인계에 포함하자고 제안한 이유",
          "그 판단의 근거가 된 교대 시간대 낙상 양상이나 수술 후 첫 보행 환자의 상황",
          "확인한 사실이 다음 근무자의 환자 상태 파악에 필요한 정보 전달로 이어지는 논리"
        ]
      },
      "question": "푸른결종합병원에서 진통제 투여 시각을 인수인계에 넣자고 제안하셨던데요, 다음 근무자에게 그 정보를 꼭 전달해야 한다고 본 근거는 무엇이었어요?",
      "answerTip": "핵심 내용을 먼저 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 투여 시각을 인수인계에 포함하자고 제안한 이유를 구체적으로 설명한다.",
            "교대 시간대 낙상 양상이나 수술 후 첫 보행 환자의 상황을 판단 근거로 제시한다.",
            "그 사실 때문에 다음 근무자가 해당 정보를 알아야 한다는 연결이 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "다음 근무자에게 진통제 투여 시각을 전달해야 한다는 이유는 제시한다.",
            "다만 관찰한 상황의 구체성이나 해당 상황과 정보 전달 필요성 사이의 연결이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트에 항목을 추가했다는 사실만 말하고 제안한 이유를 설명하지 못한다.",
            "또는 낙상 감소 성과만 제시하고 다음 근무자에게 해당 정보를 전달해야 하는 근거는 제시하지 못한다."
          ]
        }
      }
    }
  ]
}
